BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL statement_timeout='12s'; SET LOCAL lock_timeout='300ms';
WITH d AS MATERIALIZED (SELECT * FROM trading_decisions WHERE account_id IN(43002148,46130058,47790949,49236051) AND at>='2026-11-09T16:00Z' AND at<'2026-11-10T11:45Z')
SELECT jsonb_build_object('captured_at',now(),'read_only',current_setting('transaction_read_only'),
'day_decision_counts',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT account_id,symbol,kind,reason,count(*) records,min(at) first_at,max(at) last_at FROM d GROUP BY account_id,symbol,kind,reason) x),
'sizing_decisions',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT * FROM d WHERE reason ILIKE '%min_volume%' OR reason ILIKE '%margin%' OR kind ILIKE '%margin%' OR (kind='s3_pullback_state' AND reason='armed_pullback')) x),
'symbols',(SELECT jsonb_agg(to_jsonb(s)-'raw') FROM symbols s WHERE account_id IN(43002148,46130058,47790949,49236051) AND name IN('SpotCrude','SpotBrent','US500','NAS100','XAUUSD','XAGUSD','BTCUSD','ETHUSD')),
'latest_trader_reads',(SELECT jsonb_agg(to_jsonb(x)-'raw') FROM (SELECT DISTINCT ON(account_id) * FROM trader_reads WHERE account_id IN(43002148,46130058,47790949,49236051) ORDER BY account_id,id DESC) x));
ROLLBACK;
